            temp2.p[i2][4] = cr(temp2.p[i2][4] + temp2.ka[0] - temp2.ka2[0]);
            if (temp2.p[i2][5] != undefined) temp2.p[i2][5] = cr(temp2.p[i2][5] + temp2.ka[1] - temp2.ka2[1]);
            temp2.r.push(temp2.p[i2]);
